# Break My Fix finding 1, generated by Tracefix: unyt_array.to_astropy returns a wrong value.
# Property (docstring): For any dimensionless unyt_array, including scaled ratios such as km/m, the astropy quantity has the same physical value once both are reduced to pure numbers.
# Quote: Creates a new AstroPy quantity with the same unit information.
# Run it with pytest: it fails for as long as the code breaks this property.

import copy
import math

from unyt.array import unyt_array


def test_break_my_fix_1() -> None:
    self_after = unyt_array([1, 2, 3], 'km/m')
    self = copy.deepcopy(self_after)
    # The property applies to this input: self.units.is_dimensionless
    result = self_after.to_astropy()
    assert (all(math.isclose(float(a), float(b), rel_tol=1e-9, abs_tol=1e-300) for a, b in zip(result.decompose().value.ravel(), self.to('dimensionless').value.ravel())))
